from itertools import product
from slugify.slugify import _modern_truncate


def reference(text, separator, limit):
    full = text.replace('-', separator)
    if limit <= 0 or len(full) <= limit:
        return full
    emitted = []
    length = last_word_end = 0
    for char in text:
        piece = separator if char == '-' else char
        if length + len(piece) > limit:
            break
        emitted.append(piece)
        length += len(piece)
        if char != '-':
            last_word_end = length
    return ''.join(emitted)[:last_word_end]


count = 0
for size in range(6):
    for chars in product('ax-界', repeat=size):
        text = ''.join(chars)
        for separator in ('-', '::', '', 'x', 'xy'):
            for limit in range(-1, 10):
                expected = reference(text, separator, limit)
                for order in (False, True):
                    actual = _modern_truncate(text, limit, False, separator, order)
                    assert actual == expected, (text, separator, limit, actual, expected)
                    count += 1
print(f'PASS: {count} hard-cut comparisons with an independent character-by-character reference')
PY

