from humanize import natural_list

class SinglePass:
    def __init__(self, values):
        self.values = values
        self.used = False

    def __iter__(self):
        assert not self.used, 'iterable consumed more than once'
        self.used = True
        yield from self.values

for values, expected in [([], ''), ([1], '1'), ([1, 2], '1 and 2'), ([1, 2, 3], '1, 2 and 3')]:
    assert natural_list(x for x in values) == expected
    assert natural_list(SinglePass(values)) == expected
assert natural_list({'one', 'two'}) in {'one and two', 'two and one'}
print('Generator, single-pass iterable, and set checks passed')
