import humanize

checks = 0
for exponent, unit in zip(range(6, 34, 3), humanize.number.human_powers[1:11]):
    for sign in (1, -1):
        for fmt, mantissa in (("%.0f", "1"), ("%.1f", "1.0"), ("%.3f", "1.000")):
            if exponent == 6 and fmt == "%.3f":
                assert humanize.intword(sign * (10**exponent - 1), fmt) == f"{'-' if sign < 0 else ''}999.999 thousand"
            else:
                assert humanize.intword(sign * (10**exponent - 1), fmt) == f"{'-' if sign < 0 else ''}{mantissa} {unit[0]}"
            checks += 1
for value, expected in (
    (999949 * 10**18, "999.9 sextillion"),
    (10**36, "1000.0 decillion"),
    (10**100 - 1, "1.0 googol"),
    (-(10**100 - 1), "-1.0 googol"),
    (2 * 10**100, "2.0 googol"),
):
    assert humanize.intword(value) == expected
    checks += 1
print(f"{checks} boundary checks passed")
