/bin/zsh -lc python - <<'PY'
import importlib.util
import itertools
import subprocess
import sys
from slugify.slugify import _modern_truncate

checked = 0
for size in range(7):
    for chars in itertools.product('-ax', repeat=size):
        text = ''.join(chars)
        for separator in ('-', '', '::', 'x', 'xy', 'aaa'):
            full = text.replace('-', separator)
            for limit in range(1, len(full) + 2):
                if len(full) <= limit:
                    expected = full
                else:
                    pieces = []
                    length = end = 0
                    for char in text:
                        piece = separator if char == '-' else char
                        if length + len(piece) > limit:
                            break
                        pieces.append(piece)
                        length += len(piece)
                        if char != '-':
                            end = len(pieces)
                    expected = ''.join(pieces[:end])
                actual = _modern_truncate(text, limit, False, separator, False)
                assert actual == expected, (text, separator, limit, actual, expected)
                checked += 1
print(f'Independent character-by-character boundary checks: {checked} passed')
for module, arguments in (
    ('pycodestyle', ['--ignore=E128,E261,E225,E501,W605', 'slugify/slugify.py']),
    ('flake8', ['--ignore=E501,F403,F401,E241,E225,E128', 'slugify/slugify.py']),
):
    if importlib.util.find_spec(module) is None:
        print(f'{module}: unavailable; skipped')
    else:
        subprocess.run([sys.executable, '-m', module, *arguments], check=True)
        print(f'{module}: passed')
